{"type":"assistant","message":{"model":"claude-opus-4-6","id":"msg_01K7bihxHpK1M2u4xGNRXhnb","type":"message","role":"assistant","content":[{"type":"tool_use","id":"toolu_01Ni4JzZKmEqWyCceyQQnvAJ","name":"mcp__agent-ml-research__ssh_execute","input":{"server":"westd-38929","command":"cat > /root/autodl-tmp/importance_margin_vla_compress/analyze_openvla_oft_token_importance.py << 'SCRIPT_EOF'\n#!/usr/bin/env python\n\"\"\"OpenVLA-OFT Token Importance Analysis on LIBERO-Object.\n\nPruning Curve (L2 norm-based) + Per-layer Attention Entropy.\n\nUsage:\n    CUDA_VISIBLE_DEVICES=1 python analyze_openvla_oft_token_importance.py\n\"\"\"\n\nimport os\nos.environ[\"CUDA_VISIBLE_DEVICES\"] = \"1\"\nos.environ[\"HF_HOME\"] = \"/root/autodl-tmp/.hf_cache\"\nos.environ[\"HF_HUB_OFFLINE\"] = \"1\"\nos.environ[\"TRANSFORMERS_OFFLINE\"] = \"1\"\n\nimport io\nimport json\nimport math\nimport sys\nfrom collections import defaultdict\nfrom pathlib import Path\n\nimport numpy as np\nimport pyarrow.parquet as pq\nimport torch\nimport torch.nn.functional as F\nfrom PIL import Image\n\n# Model paths\nOFT_MODEL_PATH = \"/root/autodl-tmp/openvla-oft-libero-object\"\nSTD_MODEL_PATH = \"/root/autodl-tmp/openvla-libero-object\"\nLORA_ADAPTER_PATH = os.path.join(OFT_MODEL_PATH, \"lora_adapter\")\n\n# LIBERO data\nLIBERO_SNAP = Path(\"/root/autodl-tmp/.hf_cache/lerobot/hub/\"\n                   \"datasets--HuggingFaceVLA--libero/snapshots/\"\n                   \"86958911c0f959db2bbbdb107eb3e17c5f9c798e\")\nDATA_DIR = LIBERO_SNAP / \"data\" / \"chunk-000\"\n\nLIBERO_OBJECT_TASKS = range(20, 30)\nFRAMES_PER_TASK = 10\nPROMPT_TEMPLATE = \"In: What action should the robot take to {task}?\\nOut:\"\nKEEP_RATIOS = [0.1, 0.2, 0.3, 0.5, 0.7, 0.9, 0.95, 1.0]\nOUT_DIR = Path(\"/root/autodl-tmp/importance_margin_vla_compress/artifacts\")\n\n\ndef load_libero_frames():\n    tasks_meta = pq.read_table(LIBERO_SNAP / \"meta\" / \"tasks.parquet\").to_pandas()\n    task_col = \"task\" if \"task\" in tasks_meta.columns else tasks_meta.columns[0]\n    task_names = tasks_meta[task_col].tolist()\n\n    per_task_rows = defaultdict(list)\n    for pf in sorted(os.listdir(DATA_DIR)):\n        tbl = pq.read_table(DATA_DIR / pf)\n        for idx, tid in enumerate(tbl.column(\"task_index\").to_pylist()):\n            if tid in LIBERO_OBJECT_TASKS:\n                per_task_rows[tid].append((pf, idx))\n\n    frames = []\n    for tid in sorted(per_task_rows.keys()):\n        rows = per_task_rows[tid]\n        step = max(1, len(rows) // FRAMES_PER_TASK)\n        for pf, idx in rows[::step][:FRAMES_PER_TASK]:\n            tbl = pq.read_table(DATA_DIR / pf)\n            img = Image.open(io.BytesIO(\n                tbl.column(\"observation.images.image\")[idx][\"bytes\"].as_py()\n            )).convert(\"RGB\")\n            action = np.array(tbl.column(\"action\")[idx].as_py(), dtype=np.float32)\n            frames.append({\n                \"image\": img,\n                \"action\": action,\n                \"task_index\": tid,\n                \"task_desc\": task_names[tid] if tid < len(task_names) else f\"task_{tid}\",\n            })\n\n    print(f\"Loaded {len(frames)} frames from {len(set(f['task_index'] for f in frames))} tasks\")\n    return frames\n\n\ndef try_load_oft_model(device):\n    \"\"\"Load OFT model: base weights + LoRA adapter.\"\"\"\n    from transformers import AutoModelForImageTextToText, AutoProcessor\n\n    # Check if LoRA adapter is available\n    adapter_path = os.path.join(LORA_ADAPTER_PATH, \"adapter_model.safetensors\")\n    has_lora = os.path.exists(adapter_path)\n    lora_valid = False\n\n    if has_lora:\n        try:\n            import safetensors.torch\n            safetensors.torch.load_file(adapter_path)\n            lora_valid = True\n        except Exception as e:\n            print(f\"LoRA adapter invalid: {e}\")\n\n    # Load base model\n    model_path = OFT_MODEL_PATH if os.path.exists(os.path.join(OFT_MODEL_PATH, \"model-00001-of-00004.safetensors\")) else STD_MODEL_PATH\n    print(f\"Loading base model from {model_path}...\")\n    model = AutoModelForImageTextToText.from_pretrained(\n        model_path, torch_dtype=torch.float16,\n        trust_remote_code=True, low_cpu_mem_usage=True,\n    )\n\n    model_label = \"OpenVLA-7B\"\n\n    # Apply LoRA if available\n    if lora_valid:\n        try:\n            from peft import PeftModel\n            print(\"Applying LoRA adapter...\")\n            model = PeftModel.from_pretrained(model, LORA_ADAPTER_PATH)\n            model = model.merge_and_unload()\n            model_label = \"OpenVLA-OFT (LoRA merged)\"\n            print(\"LoRA merged successfully!\")\n        except Exception as e:\n            print(f\"LoRA merge failed: {e}\")\n            print(\"Proceeding with base model only.\")\n    else:\n        print(\"No valid LoRA adapter found. Using base model.\")\n\n    model = model.to(device).eval()\n    processor = AutoProcessor.from_pretrained(model_path, trust_remote_code=True)\n\n    n = sum(p.numel() for p in model.parameters())\n    print(f\"Model: {model_label}, {n/1e9:.2f}B params\")\n\n    return model, processor, model_label\n\n\ndef get_unnorm_key(model):\n    \"\"\"Find LIBERO-related normalization key.\"\"\"\n    keys = list(model.norm_stats.keys())\n    for k in keys:\n        if \"libero\" in k.lower():\n            return k\n    return keys[0] if keys else None\n\n\n@torch.no_grad()\ndef pruning_curve_analysis(model, processor, frames, device):\n    \"\"\"Pruning curve: L2 norm-based vision token zeroing.\"\"\"\n    print(\"\\n=== Pruning Curve Analysis ===\")\n\n    unnorm_key = get_unnorm_key(model)\n    action_dim = model.get_action_dim(unnorm_key)\n    print(f\"unnorm_key={unnorm_key}, action_dim={action_dim}\")\n\n    # Setup pruning hook\n    pruner_state = {\"keep_ratio\": 1.0, \"norms_cache\": None}\n\n    def projector_hook(module, input, output):\n        kr = pruner_state[\"keep_ratio\"]\n        pruner_state[\"norms_cache\"] = output.norm(dim=-1).cpu()\n        if kr >= 1.0:\n            return output\n        B, N, D = output.shape\n        norms = output.norm(dim=-1)\n        k = max(1, int(N * kr))\n        _, bottom_idx = torch.topk(norms, N - k, dim=1, largest=False)\n        mask = torch.ones(B, N, 1, device=output.device, dtype=output.dtype)\n        mask.scatter_(1, bottom_idx.unsqueeze(-1), 0.0)\n        return output * mask.expand_as(output)\n\n    hook_handle = model.projector.register_forward_hook(projector_hook)\n\n    all_results = {str(kr): [] for kr in KEEP_RATIOS}\n    gt_actions_all = []\n    all_norms = []\n\n    for fi, frame in enumerate(frames):\n        if fi % 20 == 0:\n            print(f\"  Frame {fi}/{len(frames)}...\")\n\n        prompt = PROMPT_TEMPLATE.format(task=frame[\"task_desc\"].lower())\n        inputs = processor(prompt, frame[\"image\"]).to(device, dtype=torch.float16)\n        input_ids = inputs[\"input_ids\"]\n\n        # Ensure space token at end\n        if input_ids[0, -1] != 29871:\n            input_ids = torch.cat([\n                input_ids, torch.tensor([[29871]], device=device)\n            ], dim=1)\n\n        gt_actions_all.append(frame[\"action\"])\n\n        for kr in KEEP_RATIOS:\n            pruner_state[\"keep_ratio\"] = kr\n\n            generated_ids = model.generate(\n                input_ids,\n                pixel_values=inputs[\"pixel_values\"],\n                max_new_tokens=action_dim,\n                do_sample=False,\n            )\n\n            # Decode to continuous actions\n            pred_ids = generated_ids[0, -action_dim:].cpu().numpy()\n            disc = model.vocab_size - pred_ids\n            disc = np.clip(disc - 1, 0, model.bin_centers.shape[0] - 1)\n            pred_norm = model.bin_centers[disc]\n\n            stats = model.get_action_stats(unnorm_key)\n            mask_arr = np.array(stats.get(\"mask\", np.ones(action_dim, dtype=bool)))\n            q99, q01 = np.array(stats[\"q99\"]), np.array(stats[\"q01\"])\n            pred_cont = np.where(\n                mask_arr,\n                0.5 * (pred_norm + 1) * (q99 - q01) + q01,\n                pred_norm,\n            )\n            all_results[str(kr)].append(pred_cont)\n\n        # Cache norms from k=1.0 pass\n        if pruner_state[\"norms_cache\"] is not None:\n            all_norms.append(pruner_state[\"norms_cache\"].numpy())\n\n    hook_handle.remove()\n\n    # Compute metrics\n    gt = np.array(gt_actions_all)\n    pruning_curve = {}\n    baseline_loss = None\n\n    for kr in KEEP_RATIOS:\n        preds = np.array(all_results[str(kr)])\n        l1 = float(np.mean(np.abs(preds - gt)))\n        mse = float(np.mean((preds - gt) ** 2))\n        if kr == 1.0:\n            baseline_loss = l1\n        pruning_curve[str(kr)] = {\n            \"l1_loss\": round(l1, 6),\n            \"mse_loss\": round(mse, 6),\n        }\n\n    for kr in KEEP_RATIOS:\n        pruning_curve[str(kr)][\"normalized_l1\"] = round(\n            pruning_curve[str(kr)][\"l1_loss\"] / (baseline_loss + 1e-8), 4\n        )\n\n    # Norm statistics\n    if all_norms:\n        norms_flat = np.concatenate(all_norms, axis=0).flatten()\n        norm_stats = {\n            \"mean\": round(float(np.mean(norms_flat)), 4),\n            \"std\": round(float(np.std(norms_flat)), 4),\n            \"median\": round(float(np.median(norms_flat)), 4),\n            \"min\": round(float(np.min(norms_flat)), 4),\n            \"max\": round(float(np.max(norms_flat)), 4),\n            \"n_tokens_per_image\": int(all_norms[0].shape[-1]) if all_norms else 0,\n        }\n    else:\n        norm_stats = {}\n\n    print(\"\\nPruning Curve:\")\n    for kr in KEEP_RATIOS:\n        d = pruning_curve[str(kr)]\n        print(f\"  k={kr:.2f}: L1={d['l1_loss']:.4f}, norm_L1={d['normalized_l1']:.4f}, MSE={d['mse_loss']:.6f}\")\n\n    return pruning_curve, norm_stats\n\n\n@torch.no_grad()\ndef entropy_analysis(model, processor, frames, device, max_frames=50):\n    \"\"\"Per-layer attention entropy ratio.\"\"\"\n    print(f\"\\n=== Attention Entropy Analysis (N={min(max_frames, len(frames))}) ===\")\n\n    n_layers = model.language_model.config.num_hidden_layers\n    per_layer_ent = defaultdict(list)\n    per_layer_vfrac = defaultdict(list)\n    n_vis_global = None\n\n    subset = frames[:max_frames]\n\n    for fi, frame in enumerate(subset):\n        if fi % 10 == 0:\n            print(f\"  Frame {fi}/{len(subset)}...\")\n\n        prompt = PROMPT_TEMPLATE.format(task=frame[\"task_desc\"].lower())\n        inputs = processor(prompt, frame[\"image\"]).to(device, dtype=torch.float16)\n        input_ids = inputs[\"input_ids\"]\n\n        if input_ids[0, -1] != 29871:\n            input_ids = torch.cat([\n                input_ids, torch.tensor([[29871]], device=device)\n            ], dim=1)\n\n        try:\n            output = model(\n                input_ids=input_ids,\n                pixel_values=inputs[\"pixel_values\"],\n                attention_mask=torch.ones_like(input_ids),\n                output_attentions=True,\n            )\n        except RuntimeError as e:\n            print(f\"  Frame {fi} OOM or error: {e}\")\n            torch.cuda.empty_cache()\n            continue\n\n        attentions = output.attentions\n\n        # Determine n_vis\n        if n_vis_global is None:\n            with torch.no_grad():\n                vis = model.projector(model.vision_backbone(inputs[\"pixel_values\"]))\n            n_vis_global = vis.shape[1]\n            print(f\"  Vision tokens: {n_vis_global}\")\n\n        n_vis = n_vis_global\n        seq_len = attentions[0].shape[2]\n        text_start = 1 + n_vis  # after BOS + vision tokens\n\n        if text_start >= seq_len:\n            continue\n\n        for layer_idx, attn in enumerate(attentions):\n            # attn: (1, H, S, S)\n            vis_attn = attn[0, :, text_start:, 1:1+n_vis]  # (H, T_text, N_vis)\n            full_attn = attn[0, :, text_start:, :]  # (H, T_text, S)\n\n            v_frac = (vis_attn.sum(dim=-1) / full_attn.sum(dim=-1).clamp(min=1e-10)).mean().item()\n\n            vis_sum = vis_attn.sum(dim=-1, keepdim=True).clamp(min=1e-10)\n            vis_norm = vis_attn / vis_sum\n            ent = -(vis_norm * torch.log(vis_norm + 1e-10)).sum(dim=-1)\n            ent_ratio = (ent / math.log(n_vis)).mean().item()\n\n            per_layer_ent[layer_idx].append(ent_ratio)\n            per_layer_vfrac[layer_idx].append(v_frac)\n\n        # Free attention memory\n        del attentions, output\n        torch.cuda.empty_cache()\n\n    # Aggregate\n    entropy_results = {\n        \"num_llm_layers\": n_layers,\n        \"vision_tokens\": n_vis_global,\n        \"per_layer_entropy_ratio\": {},\n        \"per_layer_entropy_std\": {},\n        \"per_layer_vision_attention_fraction\": {},\n    }\n\n    all_ent = []\n    for L in range(n_layers):\n        if per_layer_ent[L]:\n            entropy_results[\"per_layer_entropy_ratio\"][str(L)] = round(float(np.mean(per_layer_ent[L])), 4)\n            entropy_results[\"per_layer_entropy_std\"][str(L)] = round(float(np.std(per_layer_ent[L])), 4)\n            entropy_results[\"per_layer_vision_attention_fraction\"][str(L)] = round(float(np.mean(per_layer_vfrac[L])), 4)\n            all_ent.extend(per_layer_ent[L])\n\n    if all_ent:\n        entropy_results[\"overall_entropy_ratio\"] = round(float(np.mean(all_ent)), 4)\n        entropy_results[\"overall_entropy_std\"] = round(float(np.std(all_ent)), 4)\n\n    print(f\"\\nOverall entropy ratio: {entropy_results.get('overall_entropy_ratio', 'N/A')}\")\n    print(\"Per-layer breakdown:\")\n    for L in range(n_layers):\n        if str(L) in entropy_results[\"per_layer_entropy_ratio\"]:\n            e = entropy_results[\"per_layer_entropy_ratio\"][str(L)]\n            v = entropy_results[\"per_layer_vision_attention_fraction\"][str(L)]\n            print(f\"  L{L:2d}: entropy={e:.4f}, vis_frac={v:.4f}\")\n\n    return entropy_results\n\n\ndef main():\n    device = torch.device(\"cuda:0\")\n\n    model, processor, model_label = try_load_oft_model(device)\n\n    frames = load_libero_frames()\n\n    # A) Pruning Curve\n    pruning_curve, norm_stats = pruning_curve_analysis(model, processor, frames, device)\n\n    # B) Attention Entropy\n    entropy_results = entropy_analysis(model, processor, frames, device, max_frames=50)\n\n    # Save results\n    OUT_DIR.mkdir(parents=True, exist_ok=True)\n\n    pruning_out = {\n        \"model\": model_label,\n        \"model_path\": OFT_MODEL_PATH,\n        \"dataset\": \"LIBERO-Object (task_index 20-29)\",\n        \"n_frames\": len(frames),\n        \"n_tasks\": len(set(f[\"task_index\"] for f in frames)),\n        \"keep_ratios\": KEEP_RATIOS,\n        \"pruning_method\": \"L2_norm_zeroing\",\n        \"pruning_curve\": pruning_curve,\n        \"vision_token_norm_stats\": norm_stats,\n    }\n    with open(OUT_DIR / \"openvla_oft_pruning_curve.json\", \"w\") as f:\n        json.dump(pruning_out, f, indent=2)\n    print(f\"\\nSaved: {OUT_DIR / 'openvla_oft_pruning_curve.json'}\")\n\n    entropy_out = {\n        \"model\": model_label,\n        \"model_path\": OFT_MODEL_PATH,\n        \"dataset\": \"LIBERO-Object (task_index 20-29)\",\n        \"n_images\": min(50, len(frames)),\n        **entropy_results,\n    }\n    with open(OUT_DIR / \"openvla_oft_attention_entropy_perlayer.json\", \"w\") as f:\n        json.dump(entropy_out, f, indent=2)\n    print(f\"Saved: {OUT_DIR / 'openvla_oft_attention_entropy_perlayer.json'}\")\n\n    print(f\"\\n{'='*60}\")\n    print(f\"Analysis complete: {model_label}\")\n    print(f\"{'='*60}\")\n\n\nif __name__ == \"__main__\":\n    main()\nSCRIPT_EOF\necho \"Script written: $(wc -l /root/autodl-tmp/importance_margin_vla_compress/analyze_openvla_oft_token_importance.py)\"","account":"root"},"caller":{"type":"direct"}}],"stop_reason":null,"stop_sequence":null,"stop_details":null,"usage":{"input_tokens":1,"cache_creation_input_tokens"